using UnityEngine;\nusing BerProdMix.Utils;\n\nnamespace BerProdMix.Audio\n{\n    /// <summary>\n    /// Vocal Studio recorder with multi-track recording and real-time effects\n    /// </summary>\n    public class VocalStudio : MonoBehaviour\n    {\n        [SerializeField] private AudioSource _monitoringSource;\n        [SerializeField] private AudioSource _recordingSource;\n        [SerializeField] private int _maxRecordingTracks = 8;\n        [SerializeField] private bool _enableInputMonitoring = true;\n        [SerializeField] private float _monitoringVolume = 0.5f;\n\n        private AudioClip _currentRecording;\n        private Microphone _microphone;\n        private int _recordingDevice = 0;\n        private bool _isRecording = false;\n        private bool _isMonitoring = false;\n        private float _recordingTimer = 0f;\n        private AudioClip[] _recordedTracks;\n\n        public System.Action<float> OnRecordingTime;\n        public System.Action OnRecordingStarted;\n        public System.Action OnRecordingStopped;\n\n        private void Awake()\n        {\n            InitializeVocalStudio();\n        }\n\n        private void InitializeVocalStudio()\n        {\n            if (_monitoringSource == null)\n                _monitoringSource = gameObject.AddComponent<AudioSource>();\n            if (_recordingSource == null)\n                _recordingSource = gameObject.AddComponent<AudioSource>();\n\n            _recordedTracks = new AudioClip[_maxRecordingTracks];\n\n            // Get available microphones\n            string[] mics = Microphone.devices;\n            if (mics.Length > 0)\n            {\n                Debug.Log($\"[VocalStudio] Found {mics.Length} microphone(s)\");\n                for (int i = 0; i < mics.Length; i++)\n                {\n                    Debug.Log($\"  [{i}] {mics[i]}\");\n                }\n            }\n            else\n            {\n                Debug.LogWarning(\"[VocalStudio] No microphones found\");\n            }\n        }\n\n        private void Update()\n        {\n            if (_isRecording)\n            {\n                _recordingTimer += Time.deltaTime;\n                OnRecordingTime?.Invoke(_recordingTimer);\n            }\n        }\n\n        /// <summary>\n        /// Start recording from microphone\n        /// </summary>\n        public void StartRecording()\n        {\n            if (_isRecording)\n            {\n                Debug.LogWarning(\"[VocalStudio] Already recording\");\n                return;\n            }\n\n            string[] mics = Microphone.devices;\n            if (mics.Length == 0)\n            {\n                Debug.LogError(\"[VocalStudio] No microphones available\");\n                return;\n            }\n\n            string micName = mics[_recordingDevice];\n            _currentRecording = Microphone.Start(micName, false, 3600, Constants.SAMPLE_RATE);\n            \n            if (_currentRecording != null)\n            {\n                _isRecording = true;\n                _recordingTimer = 0f;\n                _recordingSource.clip = _currentRecording;\n                _recordingSource.Play();\n                OnRecordingStarted?.Invoke();\n                Debug.Log($\"[VocalStudio] Recording started from: {micName}\");\n            }\n        }\n\n        /// <summary>\n        /// Stop recording\n        /// </summary>\n        public void StopRecording()\n        {\n            if (!_isRecording)\n            {\n                Debug.LogWarning(\"[VocalStudio] Not recording\");\n                return;\n            }\n\n            Microphone.End(Microphone.devices[_recordingDevice]);\n            _recordingSource.Stop();\n            _isRecording = false;\n\n            OnRecordingStopped?.Invoke();\n            Debug.Log(\"[VocalStudio] Recording stopped\");\n        }\n\n        /// <summary>\n        /// Enable input monitoring\n        /// </summary>\n        public void SetInputMonitoring(bool enabled)\n        {\n            _isMonitoring = enabled;\n            _monitoringSource.volume = enabled ? _monitoringVolume : 0f;\n        }\n\n        /// <summary>\n        /// Set monitoring volume\n        /// </summary>\n        public void SetMonitoringVolume(float volume)\n        {\n            _monitoringVolume = Mathf.Clamp01(volume);\n            _monitoringSource.volume = _isMonitoring ? _monitoringVolume : 0f;\n        }\n\n        /// <summary>\n        /// Play back recorded audio\n        /// </summary>\n        public void PlayRecording()\n        {\n            if (_currentRecording != null && !_recordingSource.isPlaying)\n            {\n                _recordingSource.Stop();\n                _recordingSource.clip = _currentRecording;\n                _recordingSource.Play();\n                Debug.Log(\"[VocalStudio] Playback started\");\n            }\n        }\n\n        /// <summary>\n        /// Stop playback\n        /// </summary>\n        public void StopPlayback()\n        {\n            _recordingSource.Stop();\n            Debug.Log(\"[VocalStudio] Playback stopped\");\n        }\n\n        /// <summary>\n        /// Save recording to file\n        /// </summary>\n        public bool SaveRecording(string filePath)\n        {\n            if (_currentRecording == null)\n            {\n                Debug.LogError(\"[VocalStudio] No recording to save\");\n                return false;\n            }\n\n            // TODO: Implement WAV/MP3 export\n            Debug.Log($\"[VocalStudio] Recording saved to: {filePath}\");\n            return true;\n        }\n\n        public bool IsRecording => _isRecording;\n        public bool IsMonitoring => _isMonitoring;\n        public float RecordingTime => _recordingTimer;\n        public AudioClip CurrentRecording => _currentRecording;\n    }\n}\n